@using sv_04fc50b4fd6e44d7847f5f60a38d7fda.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (_loading)
    {
        <p class="loading">Loading notification preferences...</p>
    }
    else
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_emailNotifications" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Email Notifications
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_pushNotifications" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Push Notifications
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_weeklyDigest" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Weekly Digest
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(channel)"
                               @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                        @channel
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save Preferences")
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast toast-success">Preferences saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    // Available channels to mute/unmute
    private static readonly string[] _allChannels =
        ["general", "announcements", "engineering", "design", "marketing", "support"];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

{"path": "/tmp/sv-04fc50b4fd6e44d7847f5f60a38d7fda/Components/Pages/Settings/ActiveSessionsTable.razor", "file_text": "@namespace sv_04fc50b4fd6e44d7847f5f60a38d7fda.Components.Pages.Settings
@using sv_04fc50b4fd6e44d7847f5f60a38d7fda.Services

<div class="sessions-section">
    <h3>Active Sessions</h3>

    @if (Sessions.Count == 0)
    {
        <p>No active sessions.</p>
    }
    else
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm"
                                        @onclick="() => RequestRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-session-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }

    @if (_sessionToRevoke is not null)
    {
        <div class="modal-overlay">
            <div class="modal-dialog">
                <h4>Confirm Session Revocation</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                <div class="modal-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevoke" disabled="@_revoking">
                        @(_revoking ? "Revoking..." : "Revoke Session")
                    </button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke" disabled="@_revoking">
                        Cancel
                    </button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    private void RequestRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is null) return;
        _revoking = true;
        await OnRevoke.InvokeAsync(_sessionToRevoke.Id);
        _revoking = false;
        _sessionToRevoke = null;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }
}
"}

{"path": "/tmp/sv-04fc50b4fd6e44d7847f5f60a38d7fda/Components/Pages/Settings/SecuritySection.razor", "file_text": "@namespace sv_04fc50b4fd6e44d7847f5f60a38d7fda.Components.Pages.Settings
@using sv_04fc50b4fd6e44d7847f5f60a38d7fda.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Security Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>Change Password</span>
                <span class="panel-toggle">@(_passwordPanelOpen ? "▲" : "▼")</span>
            </button>

            @if (_passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="_currentPassword" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="_newPassword" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="_confirmPassword" class="form-control" />
                    </div>

                    @if (!string.IsNullOrEmpty(_passwordError))
                    {
                        <div class="error-message">@_passwordError</div>
                    }

                    <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                        @(_changingPassword ? "Updating..." : "Update Password")
                    </button>

                    @if (_passwordSuccess)
                    {
                        <div class="toast toast-success">Password updated successfully!</div>
                    }
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="twofa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="twofa-status">
                <span class="status-indicator @(_twoFactorEnabled ? "status-enabled" : "status-disabled")"></span>
                <span>@(_twoFactorEnabled ? "Enabled" : "Disabled")</span>
                <label class="toggle-label">
                    <input type="checkbox" @bind="_twoFactorEnabled" class="toggle-input" />
                    <span class="toggle-switch"></span>
                </label>
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @_lastPasswordChange.Value.ToString("f")</p>
            }
        </div>

        <!-- Active Sessions -->
        <ActiveSessionsTable Sessions="_sessions"
                             CurrentSessionId="@_currentSessionId"
                             OnRevoke="RevokeSessionAsync" />
    }
</div>

@code {
    private bool _loading = true;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _passwordError = "";
    private bool _changingPassword;
    private bool _passwordSuccess;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private string _currentSessionId = "";

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
        // Treat the first session as the current one
        _currentSessionId = _sessions.FirstOrDefault()?.Id ?? "";
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        _passwordError = "";
        _passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password is required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        _changingPassword = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _changingPassword = false;
        _passwordSuccess = true;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _sessions = _sessions.Where(s => s.Id != sessionId).ToList();
    }
}
"}

